<script>
(()=>{'use strict';
const endpoint=@json(route('bot-logs.data')),replyEndpoint=@json(route('bot-logs.reply')),csrf=@json(csrf_token()),el=id=>document.getElementById(id),cards=el('cards'),feed=el('feed'),queue=el('queue'),conn=el('connection');const roles={zebra:'GATEKEEPER',dev:'TECHNICAL',ivy:'SECRETARY',pacman:'PACKAGING'};
let snapshot=null,paused=false,initial=true,seen=new Set(),signature='',animations=new Map(),requesting=false,viewMode='log';
const make=(tag,cls,value)=>{const node=document.createElement(tag);if(cls)node.className=cls;if(value!==undefined)node.textContent=String(value);return node;};
const timestamp=t=>t&&Number.isFinite(Date.parse(t))?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(t)):'—';
function drawCards(){if(!snapshot)return;const selected=el('filter').value,fragment=document.createDocumentFragment();for(const b of snapshot.bots){const executing=!snapshot.stale&&(snapshot.feed||[]).some(m=>m.from===b.role&&m.executing===true);const card=make('button','node '+b.state+(executing?' executing':'')+([...animations.values()].some(a=>a.role===b.role)?' typing':'')+(selected===b.role?' selected':'')),top=make('div','nodehead'),id=make('div','identity'),head=make('div');card.type='button';card.dataset.role=b.role;card.setAttribute('aria-pressed',selected===b.role?'true':'false');card.setAttribute('aria-label','Show '+b.role+' sent, received and progress entries');head.append(make('div','botname',b.role.toUpperCase()),make('div','botrole',roles[b.role]||'SPECIALIST'));id.append(make('div','monogram',b.role[0].toUpperCase()),head);top.append(id,make('div','state '+b.state,b.state.toUpperCase()));const role=make('div','nodetitle',roles[b.role]||'SPECIALIST'),foot=make('div','nodefoot'),detail=make('span','node-detail',(b.state==='working'||executing)?'PROCESS ACTIVE':b.state==='waiting'?'AWAITING INPUT':b.state==='offline'?'SIGNAL UNAVAILABLE':b.state.toUpperCase()),meter=make('span','node-meter');meter.setAttribute('aria-hidden','true');for(let i=0;i<6;i++)meter.append(make('i'));foot.append(detail,meter);card.append(top,role,foot);card.addEventListener('click',()=>{el('filter').value=b.role;viewMode='queue';setView();drawCards();drawQueue();drawFeed();});fragment.append(card);}cards.replaceChildren(fragment);el('clearFilter').disabled=selected==='all';}
function messages(){return(snapshot?.feed||[]).slice().sort((a,b)=>Date.parse(b.time)-Date.parse(a.time)||b.id.localeCompare(a.id));}
function filtered(){const term=el('search').value.trim().toLowerCase(),role=el('filter').value,showSystem=el('systemEvents').checked;return messages().filter(m=>(showSystem||!['receipt','archive'].includes(m.kind))&&(role==='all'||m.from===role||m.to===role)&&(!term||[m.text,m.from,m.to,m.kind].join(' ').toLowerCase().includes(term)));}
function logRow(m,enter=false){
 const line=make('div','line '+(m.kind==='thought'?'thought':m.kind==='progress'?'progress':'')),
 stamp=make('time','stamp','['+timestamp(m.time).slice(-8)+']'),
 route=make('span','route '+m.from,m.kind==='thought'?m.from.toUpperCase()+' / SYS':m.from.toUpperCase()+' → '+m.to.toUpperCase()+':'),
 content=make('span','message',m.text),
 kind=make('span','kind '+m.kind,m.kind==='thought'?(m.executing?'IN PROGRESS':'WORK LOG'):(m.verified?'VERIFIED':m.kind.toUpperCase()));
 stamp.title=timestamp(m.time);
 if(m.kind==='thought'&&m.executing){const dots=make('span','running-dots');dots.setAttribute('aria-label','Still executing');for(let i=0;i<3;i++)dots.append(make('i','', '.'));content.append(dots);line.dataset.executing='true';}
 line.dataset.mid=m.id;if(enter)line.classList.add('enter');line.append(stamp,route,content,kind);return line;
}
let printQueue=[],activePrint=null,terminalPrompt=null;
function finishAnimations(){
 for(const [node,animation] of animations)clearInterval(animation.timer);
 animations.clear();
 if(terminalPrompt){
  if(activePrint)terminalPrompt.after(logRow(activePrint.message,true));
  for(const m of printQueue)terminalPrompt.after(logRow(m,true));
  const output=terminalPrompt.querySelector('.prompt-output');if(output)output.textContent='';
 }
 activePrint=null;printQueue=[];drawCards();
}
function printNext(prompt){
 if(activePrint||!printQueue.length)return;
 typeLine(prompt,printQueue.shift());
}
function typeLine(prompt,m){
 const route=m.kind==='thought'?m.from.toUpperCase()+' / SYS':m.from.toUpperCase()+' → '+m.to.toUpperCase()+':';
 const kind=m.kind==='thought'?(m.executing?'IN PROGRESS':'WORK LOG'):(m.verified?'VERIFIED':m.kind.toUpperCase());
 const text='['+timestamp(m.time).slice(-8)+'] '+route+' '+m.text+'  ['+kind+']';
 const node=prompt.querySelector('.prompt-output');
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||document.hidden){
  prompt.after(logRow(m,true));node.textContent='';printNext(prompt);return;
 }
 let index=0;node.textContent='';activePrint={message:m,prompt};
 const timer=setInterval(()=>{
  index=Math.min(text.length,index+Math.max(1,Math.ceil(text.length/220)));
  node.textContent=text.slice(0,index);
  if(index>=text.length){
   clearInterval(timer);animations.delete(node);
   prompt.after(logRow(m,true));node.textContent='';activePrint=null;
   drawCards();printNext(prompt);
  }
 },38);
 animations.set(node,{timer,text,role:m.from});drawCards();
}
function setView(){
 const queueOn=viewMode==='queue';
 el('viewQueue').classList.toggle('active',queueOn);
 el('viewLog').classList.toggle('active',!queueOn);
 queue.hidden=!queueOn;feed.hidden=queueOn;
}
function drawQueue(){
 if(!snapshot||!queue)return;
 const role=el('filter').value,payload=snapshot.work_queue||{cards:[],counts:{}},all=payload.cards||[];
 const rows=all.filter(c=>role==='all'||c.bot===role);
 const counts=payload.counts||{};
 el('queueCounts').textContent='NEED YOU '+((counts.need_you)||0)+' · WORKING '+((counts.working)||0)+' · WAITING CLIENT '+((counts.waiting_client)||0);
 if(role==='all'){queue.replaceChildren(make('div','empty','Select a bot contact to open its work queue.'));return;}
 if(role!=='pacman'){queue.replaceChildren(make('div','empty','No open work cards for '+role.toUpperCase()+' yet.'));return;}
 if(!rows.length){queue.replaceChildren(make('div','empty','No open Pacman case cards.'));return;}
 const fragment=document.createDocumentFragment();
 for(const card of rows){
  const box=make('div','work-card '+card.status),top=make('div','work-top');
  top.append(make('div','work-name',(card.case_name||'Case')+' · '+card.case_id),make('div','work-status '+card.status,card.label||card.status));
  box.append(top,make('div','work-job',card.job||''));
  const meta=[card.context,card.due_at?'Next chase '+card.due_at:''].filter(Boolean).join(' · ');
  if(meta)box.append(make('div','work-meta',meta));
  if(card.precedent)box.append(make('div','precedent','Using learned standing rule: '+card.precedent.answer+' (formal IP/company rules still outrank this).'));
  const actions=make('div','work-actions');
  const open=make('a','work-open','Open case');open.href=card.open_url||('/lead/'+card.case_id);
  actions.append(open);
  if(snapshot.full_access&&card.waiting_for_alex&&card.notice_id){
   const input=document.createElement('input');input.type='text';input.maxLength=500;input.placeholder='Type the answer for this issue…';
   const send=make('button','','Send');send.type='button';
   const post=async(text,remember=false)=>{
    send.disabled=true;box.classList.add('WORKING_NOW');
    try{
     const r=await fetch(replyEndpoint,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({case_id:card.case_id,notice_id:card.notice_id,answer:text,remember})});
     const data=await r.json();
     if(data.accepted){box.classList.add('resolved');box.querySelector('.work-status').textContent='WORKING NOW';}
     else send.disabled=false;
    }catch{send.disabled=false;}
   };
   send.addEventListener('click',()=>post(input.value,false));
   actions.append(input,send);
   if(card.binary){
    const yes=make('button','','✓');yes.type='button';yes.addEventListener('click',()=>post('yes'));
    const no=make('button','','✗');no.type='button';no.addEventListener('click',()=>post('no'));
    actions.append(yes,no);
   }
   const stand=make('button','','Remember for all cases');stand.type='button';stand.addEventListener('click',()=>post(input.value||'yes',true));
   actions.append(stand);
  }
  box.append(actions);fragment.append(box);
 }
 queue.replaceChildren(fragment);
}
function drawFeed(){
 if(!snapshot)return;
 const rows=filtered(),next=JSON.stringify([el('search').value,el('filter').value,el('systemEvents').checked,rows.map(x=>[x.id,x.executing,x.text])]);
 if(next===signature)return;
 const added=initial?[]:rows.filter(m=>!seen.has(m.id)),scroll=feed.scrollTop;
 finishAnimations();
 const fragment=document.createDocumentFragment(),prompt=make('div','terminal-prompt'),
 output=make('span','prompt-output'),cursor=make('span','prompt-cursor','█');
 prompt.setAttribute('aria-hidden','true');prompt.append(output,cursor);fragment.append(prompt);
 for(const m of rows)if(initial||seen.has(m.id))fragment.append(logRow(m));
 if(!rows.length)fragment.append(make('div','empty',messages().length?'No matching transmissions.':'No recorded messages yet.'));
 feed.replaceChildren(fragment);terminalPrompt=prompt;signature=next;
 feed.scrollTop=added.length?0:scroll;
 el('count').textContent=rows.length+' RECORDS · NEWEST FIRST';
 el('stats').textContent='AUTHENTICATED FEED / '+rows.length+' VISIBLE RECORDS';
 if(added.length){
  printQueue=added.slice().sort((a,b)=>Date.parse(a.time)-Date.parse(b.time)||a.id.localeCompare(b.id));
  printNext(prompt);
 }
}

async function poll(){if(paused||document.hidden||requesting)return;requesting=true;try{const r=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw Error('unavailable');const data=await r.json();if(data.schema!==2||!Array.isArray(data.bots)||!Array.isArray(data.feed))throw Error('invalid');snapshot=data;const stale=data.stale||Date.now()-Date.parse(data.generated_at)>12000;conn.classList.toggle('offline',stale);el('signal').textContent=stale?'SOURCE LAG / RETRYING':'● LIVE SOURCE CONNECTED';el('stats').textContent='SOURCE SYNC '+timestamp(data.generated_at);el('access').textContent=data.full_access?'OWNER / FULL CONVERSATIONS':'STAFF / RESTRICTED VIEW';drawCards();drawQueue();drawFeed();setView();seen=new Set(messages().map(x=>x.id));initial=false;}catch{conn.classList.add('offline');el('signal').textContent='SIGNAL LOST / RETRYING';if(!snapshot){cards.replaceChildren(make('div','empty','Status source unavailable.'));feed.replaceChildren(make('div','empty','Signed feed unavailable.'));}}finally{requesting=false;}}
const ambient=el('ambientClock');if(ambient){const updateDecor=()=>{ambient.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());};updateDecor();setInterval(updateDecor,1000);}
el('clearFilter').addEventListener('click',()=>{el('filter').value='all';viewMode='log';setView();drawCards();drawQueue();drawFeed();});el('systemEvents').addEventListener('change',drawFeed);el('search').addEventListener('input',drawFeed);el('filter').addEventListener('change',()=>{drawCards();drawQueue();drawFeed();});el('viewQueue').addEventListener('click',()=>{viewMode='queue';setView();drawQueue();});el('viewLog').addEventListener('click',()=>{viewMode='log';setView();drawFeed();});el('pause').addEventListener('click',()=>{paused=!paused;el('pause').textContent=paused?'▶ RESUME':'Ⅱ PAUSE';if(paused){finishAnimations();el('signal').textContent='FEED PAUSED';}else poll();});poll();setInterval(poll,1500);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
})();
</script>
@endpush
